\cite[Theorem~1.2]{ChenFengLiXiXu2026} \label{thm:upper-inequality}
	For every convex body  $K \in \mathcal{K}^3$,
	\begin{equation}\label{eq:main-inequality}
	V_3(\Pi K)\leq18\,V_3(K)^2.
	\end{equation}
	The constant is sharp, and every tetrahedron attains equality.

\label{thm:high-dimensional-counterexamples}
		For every integer $n\geq9$, there exists a full-dimensional polytope
		$Q_n\subset\mathbb{R}^n$ with at most $n+2$ facets, such that
		\begin{equation}\label{eq:main-lower}
			\mathcal P_n(Q_n)>
			\frac{(n+1)n^n}{n!}.
		\end{equation}

\label{prop:polytope-b-equality}
		Let $K\subset\mathbb{R}^3$ be a convex polytope.  Then
		\begin{equation}\label{eq:b-facet-condition}
			b=27V_3(K)^2
			\quad\Longleftrightarrow\quad
			\text{every three distinct facets of $K$ have a common point}.
		\end{equation}
		In particular, if $V_3(\Pi K)=18V_3(K)^2$ then $K$ is a tetrahedron.

\label{prop:c-equality-facial}
		Let $L=K^\circ$ as above. Then,
		\begin{equation}\label{eq:c-facial-equivalence}
			\begin{aligned}
				c=9v^2
				\ \ \Longleftrightarrow\quad
				\text{every two points of $\operatorname{ext} L$ lie in a common proper exposed face of $L$. }
			\end{aligned}
		\end{equation}

\label{prop:polar-classification}
		Assume that $K$ satisfies equality in \eqref{eq:main-inequality}. Then $K$
		is a generalized pyramid.

\label{prop:pyramid-formula}
		Let
		\begin{equation}\label{eq:normalized-pyramid}
			K=\operatorname{conv}\bigl((B\times\{0\})\cup\{(0,h)\}\bigr),
			\qquad h>0,\qquad A=V_2(B)>0.
		\end{equation}
		Then
		\begin{equation}\label{eq:pyramid-projection-volume}
			V_3(\Pi K)
			=\frac{Ah^2}{4}\bigl(V_2(B-B)+2A\bigr),
		\end{equation}
		and
		\begin{equation}\label{eq:pyramid-ratio}
			\frac{V_3(\Pi K)}{V_3(K)^2}
			=\frac94\left(\frac{V_2(B-B)}{A}+2\right).
		\end{equation}

Assume that equality holds in \eqref{eq:main-inequality}. Proposition \ref{prop:polar-classification} implies that \(K\) is a generalized pyramid. By affine invariance, after applying a suitable shear parallel to the base, we may assume that \(K\) has the representation in \eqref{eq:normalized-pyramid}. Combining \eqref{eq:pyramid-ratio} with the equality in \eqref{eq:main-inequality}, we obtain
		\begin{equation}\label{3.1}
		V_2(B-B)=6V_2(B).
	\end{equation}
		By the equality characterization in the planar Rogers-Shephard difference-body inequality \cite{RogersShephard1957}, identity \eqref{3.1}
		holds if and only if \(B\) is a triangle. Therefore, the generalized pyramid \(K\) with base \(B\) is a tetrahedron.

\label{prop:transfer}
		Let $n\geq2$ and 
		$\lambda\in\operatorname{relint}\Delta_{m-1}$. Suppose that $F\subset\mathbf 1^\perp\subset\mathbb{R}^m$ is an
		$n$-dimensional subspace and
		\begin{equation*}\label{eq:def-section}
			S=(\lambda+F)\cap\Delta_{m-1}.
		\end{equation*}
		Then, there exists a full-dimensional $n$-polytope $Q\subset F$ such that
		\begin{equation}\label{eq:transfer-lower}
			\mathcal P_n(Q)\geq n^n V_F(S)V_F(P_FC_m).
		\end{equation}
		In particular, if
		\begin{equation}\label{eq:section-violation}
			V_F(S)V_F(P_FC_m)>\frac{n+1}{n!},
		\end{equation}
		then $Q$ violates the conjectured inequality \eqref{eq:brannen-general}.

\label{prop:codim-one-product}
		Let $\lambda\in\operatorname{relint}\Delta_{m-1}$ and
		$t=\langle a,\lambda\rangle$.  Then
		\begin{equation}\label{eq:codim-one-product}
			V_{F_a}\bigl((\lambda+F_a)\cap\Delta_{m-1}\bigr)
			V_{F_a}(P_{F_a}C_m)
			=\frac{D(a)f_a(t)}{(m-1)!}.
		\end{equation}
		Since $m=n+2$, the strict inequality in \eqref{eq:section-violation} holds if and only if
		\begin{equation*}\label{eq:density-target}
			D(a)f_a(t)>(m-1)^2.
		\end{equation*}

\label{lem:cavalieri-section}
		Let
		\begin{equation*}\label{eq:def-I-epsilon}
			I(\varepsilon)=\int_{\Delta_8}
			\bigl(1+\varepsilon|L(p)|\bigr)^{-9}\,d\bar p.
		\end{equation*}
		Then,
		\begin{equation*}\label{eq:base-density}
			f_{a_\varepsilon}(0)=5I(\varepsilon).
		\end{equation*}
		Moreover, 
		\begin{equation}\label{eq:base-geometric-ratio}
			\Gamma_0(\varepsilon)
			:=\frac{
			V_{F_\varepsilon}((\lambda^{(0)}+F_\varepsilon)\cap\Delta_{10})
			V_{F_\varepsilon}(P_{F_\varepsilon}C_{11})}{10/9!}
			=\frac{D(a_\varepsilon)}{D(a_0)}I(\varepsilon).
		\end{equation}

\label{lem:cube-folding}
		Let $C=[-1/2,1/2]^8$ and $h(x)=x_1+\cdots+x_8$.  Then
		\begin{equation}\label{eq:cube-folding}
			\int_C|h(x)|\,dx<\int_Ch(x)^2\,dx.
		\end{equation}

\label{prop:nine-section}
		For every sufficiently small $\varepsilon>0$, the section specified by \eqref{eq:base-F-lambda} satisfies
		\begin{equation*}\label{eq:nine-section-violation}
			V_{F_\varepsilon}
			\bigl((\lambda^{(0)}+F_\varepsilon)\cap\Delta_{10}\bigr)
			V_{F_\varepsilon}(P_{F_\varepsilon}C_{11})
			>\frac{10}{9!}.
		\end{equation*}

\label{prop:all-sections}
		For every $r\geq0$,
		\begin{equation*}\label{eq:all-section-violations}
			V_{F_r}\bigl((\lambda^{(r)}+F_r)\cap\Delta_{m_r-1}\bigr)
			V_{F_r}(P_{F_r}C_{m_r})
			>\frac{n_r+1}{n_r!}.
		\end{equation*}

Since $m_r-1=10+r$ and $n_r=m_r-2$, Proposition
		\ref{prop:codim-one-product} and definition of $\Gamma_r$ imply that
		\[
			\frac{
			V_{F_r}((\lambda^{(r)}+F_r)\cap\Delta_{m_r-1})
			V_{F_r}(P_{F_r}C_{m_r})}
			{(n_r+1)/n_r!}
			=\Gamma_r>1.
		\]
